-- Mantiene fecha_actualizacion (equivalente a ON UPDATE CURRENT_TIMESTAMP de MySQL).
CREATE OR REPLACE FUNCTION set_fecha_actualizacion() RETURNS trigger AS $$ BEGIN NEW.fecha_actualizacion = CURRENT_TIMESTAMP; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_perfil_prestador_upd BEFORE UPDATE ON "perfil_prestador" FOR EACH ROW EXECUTE FUNCTION set_fecha_actualizacion();
CREATE TRIGGER trg_peticion_upd BEFORE UPDATE ON "peticion" FOR EACH ROW EXECUTE FUNCTION set_fecha_actualizacion();
CREATE TRIGGER trg_reputacion_upd BEFORE UPDATE ON "reputacion" FOR EACH ROW EXECUTE FUNCTION set_fecha_actualizacion();

-- Vistas públicas (se usan para mostrar perfiles y peticiones sin datos sensibles).
CREATE OR REPLACE VIEW "v_perfil_publico" AS
select "pp"."id_perfil" AS "id_perfil","u"."nombre_pila" AS "nombre_pila","u"."foto_perfil_url" AS "foto_perfil_url","pp"."descripcion" AS "descripcion","pp"."tarifa_sugerida" AS "tarifa_sugerida","r"."promedio" AS "calificacion_promedio","r"."servicios_terminados" AS "servicios_terminados" from (("perfil_prestador" "pp" join "usuario" "u" on(("u"."id_usuario" = "pp"."id_usuario"))) left join "reputacion" "r" on(("r"."id_usuario" = "u"."id_usuario"))) where (("pp"."activo" = true) and ("u"."id_estado_cuenta" = 2));
CREATE OR REPLACE VIEW "v_peticion_publica" AS
select "p"."id_peticion" AS "id_peticion","c"."nombre" AS "categoria","p"."descripcion" AS "descripcion","z"."estado" AS "estado","z"."municipio" AS "municipio","p"."colonia" AS "colonia","p"."monto" AS "monto","p"."fecha_programada" AS "fecha_programada","p"."hora_programada" AS "hora_programada" from ((("peticion" "p" join "cat_categoria" "c" on(("c"."id_categoria" = "p"."id_categoria"))) join "cat_zona" "z" on(("z"."id_zona" = "p"."id_zona"))) join "cat_estado_peticion" "e" on(("e"."id_estado_peticion" = "p"."id_estado_peticion"))) where (("e"."nombre" = 'En Espera') and ("p"."reportada" = false));

